css:
.outer-frame { position: relative; border: 1px dashed #334155; border-radius: 6px; padding: 0 10px 12px; background: #0d1016; min-height: 210px; }
.frame-label { font-size: 11px; color: #94a3b8; padding: 6px 0 4px; border-bottom: 1px solid #1e293b; }
.bfc-parent { border: 2px solid #38bdf8; background: rgba(56, 189, 248, 0.08); border-radius: 6px; padding: 0 10px; }
#sandbox-root.is-flow-root .bfc-parent { display: flow-root; border-color: #34d399; background: rgba(52, 211, 153, 0.08); }
.floated-box { float: left; width: 100px; height: var(--float-h, 110px); margin: 8px 12px 8px 0; border-radius: 5px; background: rgba(251, 146, 60, 0.25); border: 1px solid #fb923c; color: #fed7aa; font-size: 11px; font-weight: 600; display: flex; align-items: center; justify-content: center; text-align: center; }
.first-child { margin-top: var(--child-mt, 24px); padding: 8px 10px; border-radius: 4px; background: rgba(167, 139, 250, 0.16); border: 1px solid #a78bfa; color: #ddd6fe; font-size: 12px; }
.readout { position: absolute; left: 10px; right: 10px; bottom: 8px; font-size: 11px; color: #cbd5e1; background: #090b0f; border: 1px solid #1e293b; border-radius: 4px; padding: 5px 8px; }
